function bind(el){el.addEventListener('click',click);el.addEventListener('submit',e=>{if(e.target.id!=='ev36-add-form')return;e.preventDefault();const f=new FormData(e.target),ytId=youtubeId(f.get('url'));if(!ytId){notify('Link YouTube không hợp lệ.');return;}let v=all().find(x=>x.youtubeId===ytId&&!x.legacy);if(!v){v={id:'yt-'+ytId,youtubeId:ytId,lang:f.get('lang')==='zh'?'zh':'en',title:String(f.get('title')||'').trim().slice(0,120)||'Video YouTube '+ytId,level:String(f.get('level')),topic:String(f.get('topic')),audience:'all',custom:true,channel:'Video của tôi',lines:[]};db.custom.push(v);}if(!db.saved.includes(v.id))db.saved.push(v.id);save();open(v.id);});el.addEventListener('input',e=>{if(e.target.id==='ev36-search'){filter.q=e.target.value;refreshList();}else if(e.target.id==='ev36-answer'){answer=e.target.value;if(feedback&&(!feedback.reveal||feedback.pct===100)){if(feedback.reveal)assisted=true;feedback=null;const f=root.querySelector('#ev38-feedback');if(f)f.remove();}refreshHints();}});el.addEventListener('change',async e=>{const t=e.target;switch(t.id){case 'ev36-level':filter.level=t.value;refreshList();break;case 'ev36-topic':filter.topic=t.value;refreshList();break;case 'ev36-audience':filter.aud=t.value;refreshList();break;case 'ev36-source':dataset=t.value==='captions'?'captions':'practice';loop=false;resetLine(0);break;case 'ev38-seek':pause();stopVoice();seek(Number(t.value),false);break;case 'ev36-speed':speed=Number(t.value)||1;try{if(player())player().playbackRate=speed;if(ready&&yt)yt.setPlaybackRate(speed);}catch{}break;case 'ev36-file':{const f=t.files?.[0],token=generation;if(!f)return;if(f.size>2*1024*1024){notify('File phụ đề tối đa 2 MB.');return;}try{const raw=await f.text();if(token===generation&&!request){root.querySelector('#ev36-paste').value=raw;applyCaptions(parse(raw));}}catch{notify('Không đọc được file.');}break;}case 'ev36-local':{const f=t.files?.[0];if(!f)return;leave();local={id:'local-'+Date.now(),localUrl:URL.createObjectURL(f),lang:filter.lang==='zh'?'zh':'en',title:f.name,level:'Tự chọn',topic:'other',audience:'all',channel:'Tệp trên máy',lines:[]};open(local.id);break;}}});el.addEventListener('error',e=>{if(e.target.tagName==='IMG')e.target.style.display='none';},true);el.addEventListener('keydown',dictationKeys);}
function render(lang='all'){const el=document.getElementById('page-videos');if(!el)return;if(root!==el){root=el;bind(el);}if(lang!==sourceLang){sourceLang=lang;filter.lang=['en','zh'].includes(lang)?lang:'all';filter.level='all';if(view==='room')leave();}if(view==='room'&&active&&root.querySelector('#ev36-player'))return;library();}
